#!/usr/bin/env node
/**
 * Patches platforms/ios/Podfile (regenerated by Cordova on every prepare)
 * and the installed pods to work around two upstream issues:
 *
 * 1. Firebase 9.x ships Swift pods (e.g. FirebaseCoreInternal) that depend
 *    on Obj-C pods (e.g. GoogleUtilities) without module maps. `pod install`
 *    fails unless `use_modular_headers!` is declared in the target.
 *
 * 2. App Store rejects executables containing bitcode (Xcode 14+), but every
 *    published razorpay-pod (incl. 1.5.x) still ships an XCFramework with
 *    __LLVM/__bundle bitcode sections. Razorpay has not fixed it upstream,
 *    so we strip bitcode locally and force ENABLE_BITCODE=NO on all pods.
 *
 * What this hook does on every `cordova prepare ios`:
 *  - Injects `use_modular_headers!` inside the target block of the Podfile.
 *  - Appends a `post_install` block that disables bitcode, forces
 *    DWARF-with-dSYM, and re-strips Razorpay bitcode on every `pod install`.
 *  - Eagerly runs `xcrun bitcode_strip -r` on each slice of Razorpay.xcframework
 *    so the next archive copies a clean binary even without re-running pods.
 */
module.exports = function (context) {
  const fs = require('fs');
  const path = require('path');
  const { execFileSync } = require('child_process');

  if (process.platform !== 'darwin') {
    return;
  }

  const projectRoot = context.opts.projectRoot || path.resolve(__dirname, '../..');
  const iosPlatformDir = path.join(projectRoot, 'platforms', 'ios');
  if (!fs.existsSync(iosPlatformDir)) {
    return;
  }

  const platforms = (context.opts && context.opts.platforms) || [];
  if (platforms.length && !platforms.includes('ios')) {
    return;
  }

  patchPodfile(path.join(iosPlatformDir, 'Podfile'));
  stripBitcode(iosPlatformDir);
  scrubPbxprojOtherLdflags(iosPlatformDir);

  function patchPodfile(podfilePath) {
    if (!fs.existsSync(podfilePath)) {
      return;
    }
    let podfile = fs.readFileSync(podfilePath, 'utf8');
    let changed = false;

    // 0. One-time cleanup: remove the legacy patch block from an earlier
    //    hook iteration named `patch-ios-razorpay-bitcode`.
    const legacy = /\n*# >>> patch-ios-razorpay-bitcode[\s\S]*?# <<< patch-ios-razorpay-bitcode\n*/;
    if (legacy.test(podfile)) {
      podfile = podfile.replace(legacy, '\n');
      changed = true;
      console.log('patch-ios-podfile: removed legacy patch-ios-razorpay-bitcode block');
    }

    // 1. Insert `use_modular_headers!` as the first statement inside the
    //    `target 'X' do ... end` block (only if not already present).
    if (!/^\s*use_modular_headers!\s*$/m.test(podfile)) {
      const targetRegex = /^(target\s+['"][^'"]+['"]\s+do\s*\n)/m;
      if (targetRegex.test(podfile)) {
        podfile = podfile.replace(targetRegex, '$1\tuse_modular_headers!\n');
        changed = true;
        console.log('patch-ios-podfile: added use_modular_headers! to target block');
      }
    }

    // 2. Append the post_install block (idempotent via marker).
    const marker = '# >>> patch-ios-podfile';
    if (!podfile.includes(marker)) {
      const block = [
        '',
        marker,
        'post_install do |installer|',
        '  installer.pods_project.targets.each do |target|',
        '    target.build_configurations.each do |config|',
        "      config.build_settings['ENABLE_BITCODE'] = 'NO'",
        "      config.build_settings['DEBUG_INFORMATION_FORMAT'] = 'dwarf-with-dsym'",
        '    end',
        '  end',
        '  razorpay_xcf = File.join(installer.sandbox.root, "razorpay-pod", "Pod", "Razorpay.xcframework")',
        '  if File.directory?(razorpay_xcf)',
        '    Dir.glob(File.join(razorpay_xcf, "*", "Razorpay.framework", "Razorpay")).each do |bin|',
        '      system("xcrun", "bitcode_strip", "-r", bin, "-o", bin)',
        '    end',
        '  end',
        'end',
        '# <<< patch-ios-podfile',
        '',
      ].join('\n');
      podfile = podfile.replace(/\s*$/, '\n') + block;
      changed = true;
      console.log('patch-ios-podfile: appended post_install block');
    }

    if (changed) {
      fs.writeFileSync(podfilePath, podfile);
    }
  }

  function scrubPbxprojOtherLdflags(iosDir) {
    // Cordova's iOS template hard-codes `-framework "FBLPromises"` into
    // OTHER_LDFLAGS. There is no FBLPromises.framework — FBLPromises is just
    // the module name of the `PromisesObjC` pod (a static lib). The Pods
    // xcconfig already provides `-l"PromisesObjC"` via $(inherited), so we
    // can safely drop this entry. The same is true for any other pod-named
    // framework reference that doesn't have a matching .framework on disk.
    const pbxprojDir = fs.readdirSync(iosDir).find((entry) => {
      return entry.endsWith('.xcodeproj');
    });
    if (!pbxprojDir) {
      return;
    }
    const pbxprojPath = path.join(iosDir, pbxprojDir, 'project.pbxproj');
    if (!fs.existsSync(pbxprojPath)) {
      return;
    }
    let pbx = fs.readFileSync(pbxprojPath, 'utf8');

    // Matches two consecutive entries inside the OTHER_LDFLAGS array:
    //   "-framework",
    //   "\"FBLPromises\"",
    const badFramework = /\n\s*"-framework",\n\s*"\\"FBLPromises\\"",/g;
    if (!badFramework.test(pbx)) {
      return;
    }
    pbx = pbx.replace(badFramework, '');
    fs.writeFileSync(pbxprojPath, pbx);
    console.log('patch-ios-podfile: removed bogus -framework FBLPromises from project.pbxproj');
  }

  function stripBitcode(iosDir) {
    const xcframeworkDir = path.join(
      iosDir, 'Pods', 'razorpay-pod', 'Pod', 'Razorpay.xcframework'
    );
    if (!fs.existsSync(xcframeworkDir)) {
      return;
    }
    const slices = fs.readdirSync(xcframeworkDir).filter((entry) => {
      return fs.statSync(path.join(xcframeworkDir, entry)).isDirectory();
    });
    for (const slice of slices) {
      const binary = path.join(xcframeworkDir, slice, 'Razorpay.framework', 'Razorpay');
      if (!fs.existsSync(binary)) {
        continue;
      }
      try {
        execFileSync('xcrun', ['bitcode_strip', '-r', binary, '-o', binary], {
          stdio: 'ignore',
        });
        console.log('patch-ios-podfile: stripped bitcode from', path.relative(projectRoot, binary));
      } catch (e) {
        console.warn('patch-ios-podfile: bitcode_strip failed for', binary, e.message);
      }
    }
  }
};
